-- ── VÉRIFICATION ─────────────────────────────────────────────────
SELECT 'inscriptions_cours' AS table_name,
  COUNT(*) AS total,
  COUNT(NULLIF(paiement,'')) AS avec_paiement,
  COUNT(*) - COUNT(NULLIF(paiement,'')) AS sans_paiement
FROM inscriptions_cours WHERE saison='2025-2026'
UNION ALL
SELECT 'cours_yoga',
  COUNT(*),
  COUNT(NULLIF(paiement,'')),
  COUNT(*) - COUNT(NULLIF(paiement,''))
FROM cours_yoga WHERE saison='2025-2026';
